class Inventory:
    def __init__(self, stock=None):
        self.stock = dict(stock or {})

    def apply_orders(self, orders):
        """Apply a batch of (sku, qty) orders, reducing stock."""
        # First validate all orders and check quantities/stock availability all-or-nothing
        # "qty must be a positive int; otherwise raise ValueError (and also leave the stock unchanged)."
        # "An order cannot be filled if the SKU is unknown, or if the total quantity for that SKU across the whole batch is more than the stock (two orders for the same SKU in one batch add up)."

        # Aggregate total required quantities per SKU in the batch
        demands = {}
        for sku, qty in orders:
            if not isinstance(qty, int) or qty <= 0:
                raise ValueError("Quantity must be a positive int")
            demands[sku] = demands.get(sku, 0) + qty

        # Check availability for each SKU
        for sku, total_qty in demands.items():
            if sku not in self.stock or self.stock[sku] < total_qty:
                raise InventoryError(f"Insufficient stock or unknown SKU for {sku}")

        # If all checks pass, apply updates
        for sku, total_qty in demands.items():
            self.stock[sku] -= total_qty

    def restock(self, sku, qty):
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError("Quantity must be a positive int")
        self.stock[sku] = self.stock.get(sku, 0) + qty

    def available(self, sku):
        return self.stock.get(sku, 0)
