from inventory import Inventory, InventoryError


def test_simple_batch():
    inv = Inventory({"apple": 5, "pear": 2})
    inv.apply_orders([("apple", 2), ("pear", 1)])
    assert inv.stock == {"apple": 3, "pear": 1}


def test_cannot_go_negative():
    inv = Inventory({"apple": 1})
    with pytest.raises(InventoryError):
        inv.apply_orders([("apple", 2)])
    assert inv.stock == {"apple": 1}


def test_unknown_sku():
    inv = Inventory({"apple": 5})
    with pytest.raises(InventoryError):
        inv.apply_orders([("orange", 1)])
    assert inv.stock == {"apple": 5}


def test_combined_quantities_same_sku():
    inv = Inventory({"apple": 5})
    with pytest.raises(InventoryError):
        inv.apply_orders([("apple", 3), ("apple", 3)])
    assert inv.stock == {"apple": 5}

    # Valid combined
    inv.apply_orders([("apple", 2), ("apple", 3)])
    assert inv.stock == {"apple": 0}


def test_invalid_quantity_apply_orders():
    inv = Inventory({"apple": 5})
    with pytest.raises(ValueError):
        inv.apply_orders([("apple", 0)])
    assert inv.stock == {"apple": 5}

    with pytest.raises(ValueError):
        inv.apply_orders([("apple", -1)])
    assert inv.stock == {"apple": 5}

    with pytest.raises(ValueError):
        inv.apply_orders([("apple", "2")])
    assert inv.stock == {"apple": 5}


def test_invalid_quantity_restock():
    inv = Inventory({"apple": 5})
    with pytest.raises(ValueError):
        inv.restock("apple", 0)
    assert inv.stock == {"apple": 5}

    with pytest.raises(ValueError):
        inv.restock("apple", -5)
    assert inv.stock == {"apple": 5}

    with pytest.raises(ValueError):
        inv.restock("apple", "10")
    assert inv.stock == {"apple": 5}
